#include <bits/stdc++.h>
using namespace std;

using ll = long long;

vector<ll> to_base(ll v, ll b) {
    vector<ll> ret;
    while (v) {
        ll r = v % b;
        v /= b;
        if (r < 0) {
            r -= b;
            ++v;
        }
        ret.push_back(r);
    }
    return ret;
}

int main() {
    ll p, k;
    scanf("%lld%lld", &p, &k);

    vector<ll> ans = to_base(p, -k);

    printf("%d\n", static_cast<int>(ans.size()));
    for (ll x : ans) printf("%lld ", x);
    printf("\n");

    return 0;
}

